def seen(self, key, timestamp):
    # Remove old entries
    keys_to_remove = []
    for k, last_seen_ts in self.seen.items():
        if timestamp - last_seen_ts > self.window:
            keys_to_remove.append(k)
    for k in keys_to_remove:
        del self.seen[k]

    # Check if the current key is a duplicate
    if key not in self.seen:
        self.seen[key] = timestamp
        return False

    last_seen = self.seen[key]
    if timestamp - last_seen > self.window:
        self.seen[key] = timestamp
        return False
    else:
        return True
